Ux34SmokeProbe::Ux34SmokeProbe(TaskWorkspace& workspace,QQuickWindow* window,QString screenshot):m_workspace(workspace),m_window(window),m_screenshot(std::move(screenshot)){m_wait.start();m_inputClock.start();}
QObject* Ux34SmokeProbe::find(const char* name)const
{
    const auto key=QString::fromUtf8(name);QList<QObject*> pending{m_window};QSet<QObject*> visited;
    while(!pending.isEmpty()){auto* item=pending.takeLast();if(!item || visited.contains(item))continue;visited.insert(item);if(item->objectName()==key)return item;for(auto* child:item->children())pending.append(child);if(auto* visual=qobject_cast<QQuickItem*>(item))for(auto* child:visual->childItems())pending.append(child);if(auto* window=qobject_cast<QQuickWindow*>(item))pending.append(window->contentItem());}return nullptr;
}
bool Ux34SmokeProbe::invoke(QObject* object,const char* method,const QVariant& argument){if(!object)return false;return argument.isValid()?QMetaObject::invokeMethod(object,method,Q_ARG(QVariant,argument)):QMetaObject::invokeMethod(object,method);}
bool Ux34SmokeProbe::capture(const QString& suffix,QQuickWindow* window)const{return m_screenshot.isEmpty() || (window?window:m_window.data())->grabWindow().save(m_screenshot+QStringLiteral(".ux34-")+suffix+QStringLiteral(".png"));}
QString Ux34SmokeProbe::advance()
{
    if(!m_window)return QStringLiteral("UX34 main window destroyed");if(m_workspace.busy())return {};
    auto* panel=find("calendarPanel");auto* editor=find("taskEditor");auto* title=find("editTaskTitle");
    if(!panel || !editor || !title)return QStringLiteral("UX34 controls missing");
    auto fail=[this](const QString& text){return QStringLiteral("UX34 stage %1: ").arg(m_stage)+text;};
    auto mouse=[&](QEvent::Type type,const QPointF& at,Qt::MouseButton button,Qt::MouseButtons buttons){QMouseEvent event(type,at,m_window->mapToGlobal(at),button,buttons,Qt::NoModifier);event.setTimestamp(m_inputClock.elapsed()+m_inputSequence++);QCoreApplication::sendEvent(m_window,&event);};
    auto settle=[&]{m_window->grabWindow();return m_wait.elapsed()>120;};
    if(m_stage==0){invoke(editor,"close");m_workspace.setPreference("listShowSubtasks",true);m_workspace.setTextScale(1);m_workspace.setThemeMode(1);m_window->resize(1280,800);m_workspace.clearError();if(!m_workspace.saveCatalog({{"kind","project"},{"title",QStringLiteral("时间工作区验收")}}))return fail("create category");}
    else if(m_stage==1){for(const auto& item:m_workspace.categoryTree())if(item.toMap().value("title")==QStringLiteral("时间工作区验收"))m_scope="project:"+item.toMap().value("id").toString();if(m_scope.isEmpty())return fail("category identity");m_workspace.setView(m_scope);if(!m_workspace.createForTime(QStringLiteral("讨论方案"),m_workspace.dateOffset(0),540))return fail("timed create");}
    else if(m_stage==2){for(const auto& task:m_workspace.tasks()->items())if(task.title==QStringLiteral("讨论方案"))m_first=task.id;if(m_first.isEmpty())return fail("first task identity");if(!m_workspace.createForTime(QStringLiteral("整理设计"),m_workspace.dateOffset(0),570))return fail("overlap create");}
    else if(m_stage==3){for(const auto& task:m_workspace.tasks()->items())if(task.title==QStringLiteral("整理设计"))m_second=task.id;if(m_second.isEmpty())return fail("second task identity");if(!m_workspace.createForDate(QStringLiteral("检查清单项"),m_workspace.dateOffset(0)))return fail("date task create");}
    else if(m_stage==4){m_workspace.selectCalendarDate(m_workspace.dateOffset(0));m_workspace.setView("week");}
    else if(m_stage==5){if(!settle())return {};const auto map=m_workspace.timelineFor(m_workspace.dateOffset(0),true);if(map.value("blocks").toList().size()!=2 || map.value("days").toList().size()!=7 || m_workspace.scope()!=m_scope)return fail("scoped week contents");auto* block=find((QStringLiteral("calendarTimeBlock-")+m_first).toUtf8().constData());if(!block || !block->property("visible").toBool() || !capture("week-light"))return fail("hour block visible");invoke(m_window,"openEditor",m_first);}
    else if(m_stage==6){if(!settle())return {};if(!editor->property("visible").toBool() || m_window->property("editId")!=m_first || m_window->property("inspectorExpanded").toBool() || !capture("inspector-nearby"))return fail("nearby shared inspector");title->setProperty("text",QStringLiteral("讨论方案已更新"));invoke(m_window,"returnFromDetails");}
    else if(m_stage==7){if(editor->property("visible").toBool() || m_workspace.task(m_first).value("title")!=QStringLiteral("讨论方案已更新"))return fail("inspector exit autosave");m_workspace.setView("day");}
    else if(m_stage==8){if(!settle())return {};if(!capture("day-light"))return fail("day capture");m_before=m_workspace.task(m_first);auto* block=qobject_cast<QQuickItem*>(find((QStringLiteral("calendarTimeBlock-")+m_first).toUtf8().constData()));if(!block)return fail("time drag target");const auto from=block->mapToScene(QPointF(block->width()*0.4,12));const auto to=from+QPointF(0,96);auto send=[&](QEvent::Type type,const QPointF& at,Qt::MouseButton button,Qt::MouseButtons buttons){QMouseEvent event(type,at,m_window->mapToGlobal(at),button,buttons,Qt::NoModifier);QCoreApplication::sendEvent(m_window,&event);};send(QEvent::MouseButtonPress,from,Qt::LeftButton,Qt::LeftButton);send(QEvent::MouseMove,to,Qt::NoButton,Qt::LeftButton);if(m_workspace.task(m_first)!=m_before)return fail("drag preview wrote before release");send(QEvent::MouseButtonRelease,to,Qt::LeftButton,Qt::NoButton);}
    else if(m_stage==9){const auto task=m_workspace.task(m_first);if(task.value("schedule").toMap().value("startTime")!="11:00" || task.value("projectId")!=m_before.value("projectId"))return fail("time move same identity and scope");m_before=task;invoke(m_window,"openEditor",m_first);title->setProperty("text",QString());invoke(m_window,"returnFromDetails");invoke(panel,"step",1);}
    else if(m_stage==10){if(!editor->property("visible").toBool() || !m_window->property("draftDirty").toBool() || m_workspace.calendarDate()!=m_workspace.dateOffset(0) || m_workspace.errorText().isEmpty() || m_workspace.task(m_first)!=m_before || !capture("failed-close-preserves-draft"))return fail("failed close protection");title->setProperty("text",m_before.value("title"));m_window->setProperty("draftDirty",false);invoke(editor,"close");m_workspace.clearError();m_workspace.setView("year");}
    else if(m_stage==11){if(!settle())return {};if(m_workspace.calendarMonthsFor(m_workspace.dateOffset(0)).size()!=12 || m_workspace.task(m_first)!=m_before || !capture("year-light"))return fail("year readonly navigation");m_workspace.setTextScale(2);m_workspace.setThemeMode(2);m_window->resize(880,580);}
    else if(m_stage==12){if(!settle())return {};if(!capture("year-dark-200"))return fail("large year capture");m_workspace.setView("day");}
    else if(m_stage==13){if(!settle())return {};if(!capture("day-dark-200"))return fail("large day capture");invoke(m_window,"openEditor",m_first);}
    else if(m_stage==14){if(!settle())return {};if(!m_window->property("inspectorExpanded").toBool() || !capture("inspector-dark-200"))return fail("large inspector expanded");invoke(find("editStartDate"),"openPicker");}
    else if(m_stage==15){if(!settle())return {};auto* picker=find("taskInspectorPicker");if(!picker || !picker->property("active").toBool() || !capture("single-picker-dark-200"))return fail("single layer date selector");invoke(picker,"close");m_window->setProperty("draftDirty",false);invoke(editor,"close");m_workspace.setTextScale(1);m_workspace.setThemeMode(1);m_window->resize(1280,800);invoke(m_window,"openTool",QStringLiteral("settings"));}
    else if(m_stage==16){if(!settle())return {};auto* settings=qobject_cast<QQuickWindow*>(find("settingsDialog"));if(!settings || !settings->isVisible() || !capture("settings-window",settings))return fail("independent settings window");invoke(settings,"close");m_workspace.setView("month");}
    else if(m_stage==17){if(!settle())return {};if(!capture("month-scoped"))return fail("month capture");invoke(m_window,"openEditor",m_first);invoke(m_window,"selectEditorTab",1);auto* input=find("newSubtaskTitle");input->setProperty("text",QStringLiteral("确认结果"));invoke(input,"accepted");}
    else if(m_stage==18){if(!settle())return {};const auto children=m_workspace.subtaskChoices(m_first);if(children.size()!=1 || !capture("subtask-panel"))return fail("child list");auto* completion=qobject_cast<QQuickItem*>(find((QStringLiteral("completeSubtask-")+children.first().toMap().value("taskId").toString()).toUtf8().constData()));if(!completion || !completion->isVisible() || completion->width()<24)return fail("child completion visibly reachable");invoke(editor,"close");m_workspace.setView(m_scope);}
    else if(m_stage==19){if(!settle())return {};if(!capture("list-scoped") || m_workspace.tasks()->rowCount()!=4)return fail("scope list and nested child");if(!m_workspace.createTask(QStringLiteral("拖入时间轴")))return fail("unscheduled task create");}
    else if(m_stage==20){for(const auto& task:m_workspace.tasks()->items())if(task.title==QStringLiteral("拖入时间轴"))m_unscheduled=task.id;if(m_unscheduled.isEmpty())return fail("unscheduled identity");m_workspace.setView("day");invoke(find("unscheduledDrawer"),"open");}
    else if(m_stage==21){if(!settle())return {};auto* row=qobject_cast<QQuickItem*>(find(("unscheduledTask-"+m_unscheduled).toUtf8().constData()));auto* day=qobject_cast<QQuickItem*>(find(("calendarTimelineDay-"+m_workspace.dateOffset(0)).toUtf8().constData()));if(!row || !day)return fail("drawer drag controls");m_before=m_workspace.task(m_unscheduled);const auto from=row->mapToScene(QPointF(row->width()/2,row->height()/2)),to=day->mapToScene(QPointF(day->width()*0.3,13*60*0.8));mouse(QEvent::MouseButtonPress,from,Qt::LeftButton,Qt::LeftButton);mouse(QEvent::MouseMove,to,Qt::NoButton,Qt::LeftButton);if(m_workspace.task(m_unscheduled)!=m_before)return fail("drawer preview wrote data");mouse(QEvent::MouseButtonRelease,to,Qt::LeftButton,Qt::NoButton);}
    else if(m_stage==22){const auto task=m_workspace.task(m_unscheduled);if(task.value("schedule").toMap().value("startTime")!="13:00" || task.value("projectId")!=m_before.value("projectId"))return fail("drawer drop assigns actual time and preserves category");invoke(find("unscheduledDrawer"),"close");m_before=task;auto* block=qobject_cast<QQuickItem*>(find(("calendarTimeBlock-"+m_unscheduled).toUtf8().constData()));if(!block)return fail("new block after drop");const auto from=block->mapToScene(QPointF(block->width()*0.3,block->height()-2)),to=from+QPointF(0,24);mouse(QEvent::MouseButtonPress,from,Qt::LeftButton,Qt::LeftButton);mouse(QEvent::MouseMove,to,Qt::NoButton,Qt::LeftButton);if(m_workspace.task(m_unscheduled)!=m_before)return fail("resize wrote before release");mouse(QEvent::MouseButtonRelease,to,Qt::LeftButton,Qt::NoButton);}
    else if(m_stage==23){const auto task=m_workspace.task(m_unscheduled);if(task.value("schedule").toMap().value("startTime")!="13:00" || task.value("schedule").toMap().value("endTime")!="14:30")return fail("edge resize preserves other endpoint");m_before=task;auto* block=qobject_cast<QQuickItem*>(find(("calendarTimeBlock-"+m_unscheduled).toUtf8().constData()));const auto from=block->mapToScene(QPointF(block->width()*0.3,14)),to=from+QPointF(0,48);mouse(QEvent::MouseButtonPress,from,Qt::LeftButton,Qt::LeftButton);mouse(QEvent::MouseMove,to,Qt::NoButton,Qt::LeftButton);QKeyEvent escape(QEvent::KeyPress,Qt::Key_Escape,Qt::NoModifier);QCoreApplication::sendEvent(m_window,&escape);mouse(QEvent::MouseButtonRelease,to,Qt::LeftButton,Qt::NoButton);if(m_workspace.task(m_unscheduled)!=m_before)return fail("escape drag changed task");}
    else if(m_stage==24){auto* day=qobject_cast<QQuickItem*>(find(("calendarTimelineDay-"+m_workspace.dateOffset(0)).toUtf8().constData()));if(!day)return fail("create range day");const auto from=day->mapToScene(QPointF(day->width()*0.75,15*60*0.8)),to=from+QPointF(0,36);mouse(QEvent::MouseButtonPress,from,Qt::LeftButton,Qt::LeftButton);mouse(QEvent::MouseMove,to,Qt::NoButton,Qt::LeftButton);mouse(QEvent::MouseButtonRelease,to,Qt::LeftButton,Qt::NoButton);}
    else if(m_stage==25){if(!settle())return {};auto* popup=find("calendarCreatePopup");if(!popup || !popup->property("visible").toBool() || panel->property("newDuration").toInt()!=45 || !capture("drag-create-range"))return fail("drag creation duration");auto* input=find("calendarCreateTitle");input->setProperty("text",QStringLiteral("拖出45分钟安排"));invoke(input,"accepted");}
    else if(m_stage==26){if(!settle())return {};bool found=false;for(const auto& value:m_workspace.timelineFor(m_workspace.dateOffset(0),false).value("blocks").toList()){const auto task=value.toMap(),schedule=task.value("schedule").toMap();if(task.value("title")==QStringLiteral("拖出45分钟安排") && schedule.value("startTime")=="15:00" && schedule.value("endTime")=="15:45" && task.value("projectId")==m_before.value("projectId"))found=true;}if(!found)return fail("created range duration and identity");invoke(editor,"close");m_before=m_workspace.task(m_unscheduled);if(!m_workspace.saveTaskWithDetails(m_unscheduled,m_before.value("rowVersion").toLongLong(),m_before.value("title").toString(),m_before.value("notes").toString(),"ACTIVE","2026-10-12","2026-10-15",false,{{"schedule",QVariant()}}))return fail("date range fixture");m_workspace.selectCalendarDate("2026-10-12");m_workspace.setView("month");}
    else if(m_stage==27){if(!settle())return {};auto* band=qobject_cast<QQuickItem*>(find(("calendarTaskRange-"+m_unscheduled).toUtf8().constData()));auto* day=qobject_cast<QQuickItem*>(find("calendarDay-2026-10-14"));if(!band || !day){if(m_wait.elapsed()<1800)return {};capture("missing-month-target");auto* grid=find("calendarMonthGrid");qCritical()<<"Month target state"<<m_workspace.calendarDate()<<grid->property("anchorDate")<<grid->property("focusAnchor")<<grid->property("visibleFrom")<<grid->property("visibleThrough")<<grid->property("layoutReady")<<grid->property("height");return fail(QStringLiteral("month range drag targets: band=%1 day=%2").arg(band!=nullptr).arg(day!=nullptr));}m_before=m_workspace.task(m_unscheduled);const auto from=band->mapToScene(QPointF(20,band->height()/2)),to=day->mapToScene(QPointF(day->width()/2,day->height()/2));mouse(QEvent::MouseButtonPress,from,Qt::LeftButton,Qt::LeftButton);mouse(QEvent::MouseMove,to,Qt::NoButton,Qt::LeftButton);if(m_workspace.task(m_unscheduled)!=m_before)return fail("month preview wrote before release");mouse(QEvent::MouseButtonRelease,to,Qt::LeftButton,Qt::NoButton);}
    else if(m_stage==28){const auto task=m_workspace.task(m_unscheduled);if(task.value("startOn")!="2026-10-14" || task.value("deadlineOn")!="2026-10-17")return fail("month whole move keeps date duration");if(!capture("month-moved-range"))return fail("moved range capture");m_workspace.setView(m_scope);}
    else if(m_stage==29){if(!settle())return {};auto* list=find("taskList");list->setProperty("currentIndex",m_workspace.taskIndex(m_unscheduled));m_window->grabWindow();find("taskSearch")->setProperty("text",QStringLiteral("讨论方案"));}
    else if(m_stage==30){if(m_wait.elapsed()<300)return {};if(m_workspace.tasks()->rowCount()!=1 || m_workspace.tasks()->items().first().id!=m_first)return fail("search membership");find("taskSearch")->setProperty("text",QString());}
    else if(m_stage==31){if(m_wait.elapsed()<300)return {};auto* list=find("taskList");auto* current=qvariant_cast<QObject*>(list->property("currentItem"));if(!current || current->property("taskId")!=m_unscheduled || m_workspace.scope()!=m_scope || !capture("search-return-restores-task"))return fail("search returns to same task anchor");if(QGuiApplication::platformName()==QStringLiteral("cocoa"))invoke(m_window,"openEditor",m_first);}
    else if(m_stage==32){
        if(QGuiApplication::platformName()==QStringLiteral("cocoa")){
            if(!settle())return {};QAction* select=nullptr;
            for(auto* widget:QApplication::allWidgets())if(auto* menu=qobject_cast<QMenuBar*>(widget))select=menu->findChild<QAction*>(QStringLiteral("native-edit-selectAll"));
            if(!select || !title->property("activeFocus").toBool())return fail("native edit menu target");select->trigger();
            if(title->property("selectedText")!=title->property("text"))return fail("native select all reaches focused editor");invoke(editor,"close");
        }
        m_before=m_workspace.task(m_first);invoke(m_window,"openEditor",m_first);title->setProperty("text",QStringLiteral("编辑与改期原子衔接"));
        if(!QMetaObject::invokeMethod(m_window,"moveCalendarTask",Q_ARG(QVariant,QVariant(m_first)),Q_ARG(QVariant,m_before.value("rowVersion")),Q_ARG(QVariant,QVariant(QString())),Q_ARG(QVariant,QVariant(m_workspace.dateOffset(0))),Q_ARG(QVariant,QVariant(600)),Q_ARG(QVariant,QVariant(QStringLiteral("move")))))return fail("calendar command gateway");
    }
    else if(m_stage==33){const auto task=m_workspace.task(m_first);if(task.value("title")!=QStringLiteral("编辑与改期原子衔接") || task.value("schedule").toMap().value("startTime")!="10:00" || task.value("rowVersion").toLongLong()!=m_before.value("rowVersion").toLongLong()+2 || editor->property("visible").toBool())return fail("own draft save rebases time move without losing fields");return QStringLiteral("DONE");}
    qInfo()<<"UX34 scenario"<<m_stage<<"complete";++m_stage;m_wait.restart();return {};
}
